package com.javasmyths.highguard;
import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import com.javasmyths.highguard.book2.*;
public class HighGuardCheck {
 static int checks=0;static void yes(boolean ok,String reason){checks++;if(!ok)throw new AssertionError(reason);}static void equal(double actual,double expected,String reason){yes(Math.abs(actual-expected)<.000001,reason+": "+actual+" != "+expected);}
 static HighGuardRules.Line line(HighGuardRules.Report r,String prefix){return r.lines.stream().filter(x->x.name.startsWith(prefix)).findFirst().orElseThrow(()->new AssertionError("Missing "+prefix));}
 public static void main(String[] args)throws Exception {
  for(String p:new String[]{"escort","courier","cruiser"}){HighGuardRules.Report r=HighGuardRules.calculate(Design.preset(p));yes(r.valid,p+" preset invalid: "+r.errors);}
  Design d=new Design();d.hull=10000;d.tl=15;d.jump=6;d.maneuver=6;d.power=6;d.computer="6";d.batteries.clear();HighGuardRules.Report r=HighGuardRules.calculate(d);equal(r.energy,600,"10,000t / P6 energy example");equal(r.jumpFuel,6000,"Akron jump fuel example");equal(r.plantFuel,600,"Akron plant fuel example");equal(line(r,"Jump drive").tons,700,"J6 drive percent");equal(line(r,"Maneuver drive").tons,1700,"M6 drive percent");
  d=new Design();d.hull=100;d.tl=9;d.jump=0;d.maneuver=1;d.power=1;d.computer="1";d.armor=3;d.batteries.clear();r=HighGuardRules.calculate(d);equal(line(r,"Additional hull armor").tons,16,"100t TL9 armor-3 published example");equal(line(r,"Additional hull armor").mcr,9.6,"Armor cost example");
  equal(Catalog.WEAPONS.get("beam").factor(3,12),3,"Single triple beam turret");equal(Catalog.WEAPONS.get("beam").factor(6,12),4,"Two triple beam turrets");equal(Catalog.WEAPONS.get("beam").factor(15,12),6,"Five triple beam turrets");equal(Catalog.WEAPONS.get("beam").factor(30,12),8,"Ten triple beam turrets");equal(Catalog.WEAPONS.get("beam").factor(30,13),9,"TL13 laser bonus");equal(Catalog.WEAPONS.get("missile").factor(18,13),6,"Published 18-rack TL13 example");equal(Catalog.WEAPONS.get("plasma").factor(16,12),6,"Published plasma TL bonus example");
  d=new Design();d.hull=50000;d.tl=15;d.power=10;d.computer="6";d.batteries.clear();d.batteries.add(new Design.Battery("particle100",15,1,1));d.batteries.add(new Design.Battery("beam",100,3,10));d.batteries.add(new Design.Battery("missile",50,3,10));d.batteries.add(new Design.Battery("sand",80,3,10));r=HighGuardRules.calculate(d);yes(r.valid,"50,000t battery example: "+r.errors);int[] expected={12,8,4,6};for(int i=0;i<4;i++)equal(r.batteries.get(i).bearing,expected[i],"Published bearing example "+i);equal(HighGuardRules.bearing(1000000),.5,"Largest hull minimum 50% bearing");
  d.batteries.clear();d.spinal="Meson-A";d.batteries.add(new Design.Battery("missile100",20,1,1));r=HighGuardRules.calculate(d);equal(r.hardpoints,250,"Published spinal/bay hardpoint allocation example");
  d=Design.preset("courier");d.power=1;yes(!HighGuardRules.calculate(d).valid,"Plant below jump rejected");d=Design.preset("courier");d.tl=12;yes(!HighGuardRules.calculate(d).valid,"TL15 jump-6 rejected at TL12");d=new Design();d.fuel=Double.NaN;yes(!HighGuardRules.calculate(d).valid,"NaN fuel rejected");d=new Design();d.cargo=-.5;yes(!HighGuardRules.calculate(d).valid,"Negative fractional auto value rejected");d=new Design();d.hull=1000001;yes(!HighGuardRules.calculate(d).valid,"Hull ceiling enforced");d=new Design();d.configuration=7;d.armor=1;yes(!HighGuardRules.calculate(d).valid,"Dispersed hull armor rejected");d=new Design();d.configuration=8;d.scoops=false;d.armor=0;r=HighGuardRules.calculate(d);equal(r.armor,3,"Planetoid free armor");equal(line(r,"Planetoid structural").tons,400,"Planetoid waste");
  d=new Design();d.tl=15;d.spinal="Meson-J";d.batteries.clear();d.batteries.add(new Design.Battery("meson50",1,1,1));yes(!HighGuardRules.calculate(d).valid,"Spinal/secondary exclusion");d=new Design();d.batteries.clear();d.batteries.add(new Design.Battery("beam",3,3,2));yes(!HighGuardRules.calculate(d).valid,"Incomplete battery rejected");d=new Design();d.tl=15;d.power=6;d.batteries.clear();d.batteries.add(new Design.Battery("beam",1,3,1));d.batteries.add(new Design.Battery("beam",2,3,2));yes(!HighGuardRules.calculate(d).valid,"Different battery factors rejected");d=new Design();d.frozenWatch=true;yes(!HighGuardRules.calculate(d).valid,"Frozen watch needs additional low berths");
  d=new Design();d.batteries.clear();d.craft.add(new Design.Craft("Test fighter",10,18,2,1));r=HighGuardRules.calculate(d);equal(line(r,"Carried").tons,26,"Large carrier small-craft allowance");d.hull=1000;r=HighGuardRules.calculate(d);equal(line(r,"Carried").tons,20,"1,000t craft allowance boundary");d=new Design();d.dropTanks=100;r=HighGuardRules.calculate(d);equal(r.disposableCost,.11,"Drop tank price");
  Map<String,Object> source=new LinkedHashMap<>();source.put("schemaVersion",1);source.put("savedAt","test");source.put("design",ShipDesign.trader());byte[] bytes=new ObjectMapper().writeValueAsBytes(source);Design copy=Book2Import.convert(bytes);yes(copy.id.isEmpty(),"Import creates new identity");yes(copy.sourceJson.equals(new String(bytes,java.nio.charset.StandardCharsets.UTF_8)),"Original JSON byte snapshot preserved");yes(copy.hull==200&&copy.jump==1,"Book 2 performance transferred");yes(!copy.importNotes.isEmpty()&&!copy.importReviewed,"Conversion requires review");yes(!HighGuardRules.calculate(copy).valid,"Unacknowledged conversion cannot be saved");yes(ShipDesign.trader().hull==200,"Original object unmodified");
  Random random=new Random(1980);for(int i=0;i<1000;i++){Design x=new Design();x.hull=100+random.nextInt(999901);x.tl=7+random.nextInt(9);x.configuration=1+random.nextInt(9);x.jump=random.nextInt(7);x.maneuver=random.nextInt(7);x.power=1+random.nextInt(50);x.armor=random.nextInt(16);x.damper=random.nextInt(10);x.meson=random.nextInt(10);x.computer="9fib";HighGuardRules.Report q=HighGuardRules.calculate(x);yes(Double.isFinite(q.totalMcr)&&Double.isFinite(q.used),"Finite randomized result");yes(q.agility<=x.maneuver,"Agility cap");}
  System.out.println("PASS: "+checks+" checks; published fuel, armor, battery factors, bearing and hardpoint examples; presets, imports, invalid designs, 1,000 randomized designs.");
 }
}
